package dev.kelmagic.server;
import dev.kelmagic.*;import dev.kelmagic.core.*;import com.mojang.brigadier.*;import com.mojang.brigadier.arguments.*;import net.minecraft.commands.*;import net.minecraft.commands.arguments.EntityArgument;import net.minecraft.network.chat.Component;import net.minecraft.core.*;import net.minecraft.core.registries.Registries;import net.minecraft.world.level.levelgen.structure.PoolElementStructurePiece;import net.minecraft.world.level.levelgen.structure.pools.StructurePoolElement;import net.minecraft.nbt.NbtOps;import net.minecraft.server.level.ServerPlayer;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;
@EventBusSubscriber(modid=KelMagic.MODID) public final class MagicCommands {
 @SubscribeEvent public static void register(net.neoforged.neoforge.event.RegisterCommandsEvent e){register(e.getDispatcher());}
 public static void register(CommandDispatcher<CommandSourceStack> d){
  var root=Commands.literal("kelmagic").then(Commands.literal("help").executes(c->help(c.getSource())));
  var admin=Commands.literal("admin").requires(s->s.hasPermission(2));
  admin.then(Commands.literal("mana").then(Commands.literal("current").then(Commands.argument("players",EntityArgument.players()).then(Commands.argument("value",DoubleArgumentType.doubleArg(0,1024)).executes(c->{var list=EntityArgument.getPlayers(c,"players");for(var p:list)setCurrent(p,DoubleArgumentType.getDouble(c,"value"));return done(c.getSource(),list.size());}))))
   .then(Commands.literal("maximum").then(Commands.argument("players",EntityArgument.players()).then(Commands.literal("reset").executes(c->{var list=EntityArgument.getPlayers(c,"players");for(var p:list){p.setData(MagicAttachments.BASE_MANA_MAX,-1d);setCurrent(p,p.getData(MagicAttachments.MANA).current());}return done(c.getSource(),list.size());})).then(Commands.argument("value",DoubleArgumentType.doubleArg(0,974)).executes(c->{var list=EntityArgument.getPlayers(c,"players");for(var p:list)setMaximum(p,DoubleArgumentType.getDouble(c,"value"));return done(c.getSource(),list.size());})))));
  admin.then(Commands.literal("heart").then(Commands.argument("players",EntityArgument.players()).then(Commands.argument("enabled",BoolArgumentType.bool()).executes(c->{var list=EntityArgument.getPlayers(c,"players");for(var p:list)setHeart(p,BoolArgumentType.getBool(c,"enabled"));return done(c.getSource(),list.size());}))));
  admin.then(Commands.literal("status").then(Commands.argument("player",EntityArgument.player()).executes(c->{var p=EntityArgument.getPlayer(c,"player");c.getSource().sendSuccess(()->Component.literal(p.getScoreboardName()+": "+p.getData(MagicAttachments.MANA).current()+" / "+MagicServer.maximum(p)+"; heart="+p.getData(MagicAttachments.MANA).dragonUpgrade()+"; baseOverride="+p.getData(MagicAttachments.BASE_MANA_MAX)),false);return 1;})));
  admin.then(Commands.literal("cast").then(Commands.argument("player",EntityArgument.player()).then(Commands.argument("rite",StringArgumentType.word()).suggests((c,b)->SharedSuggestionProvider.suggest(GrandSpells.ALL.stream().map(GrandSpells.Rite::id),b)).executes(c->cast(c.getSource(),EntityArgument.getPlayer(c,"player"),StringArgumentType.getString(c,"rite"),0)).then(Commands.argument("muk",IntegerArgumentType.integer(0,100)).executes(c->cast(c.getSource(),EntityArgument.getPlayer(c,"player"),StringArgumentType.getString(c,"rite"),IntegerArgumentType.getInteger(c,"muk")))))));
  admin.then(Commands.literal("locate").then(Commands.literal("cancel").executes(c->dev.kelmagic.worldgen.ArchiveSearch.cancel(c.getSource()))).then(Commands.literal("archive").executes(c->locate(c.getSource(),16)).then(Commands.argument("chunks",IntegerArgumentType.integer(1,64)).executes(c->locate(c.getSource(),IntegerArgumentType.getInteger(c,"chunks"))))));
  root.then(admin);root.executes(c->help(c.getSource()));d.register(root);
 }
 public static void setCurrent(ServerPlayer p,double value){var m=p.getData(MagicAttachments.MANA);p.setData(MagicAttachments.MANA,m.withCurrent(Math.clamp(value,0,MagicServer.maximum(p))));MagicServer.sync(p);}
 public static void setMaximum(ServerPlayer p,double value){p.setData(MagicAttachments.BASE_MANA_MAX,Math.clamp(value,0,974));setCurrent(p,p.getData(MagicAttachments.MANA).current());}
 public static void setHeart(ServerPlayer p,boolean enabled){var m=p.getData(MagicAttachments.MANA);p.setData(MagicAttachments.MANA,new MagicAttachments.Mana(m.current(),enabled));if(enabled)net.neoforged.neoforge.network.PacketDistributor.sendToPlayersTrackingEntityAndSelf(p,new dev.kelmagic.network.HeartActivation(p.getId()));setCurrent(p,m.current());}
 private static int done(CommandSourceStack s,int n){s.sendSuccess(()->Component.translatable("commands.kelmagic.updated",n),true);return n;}
 private static int help(CommandSourceStack s){s.sendSuccess(()->Component.translatable("commands.kelmagic.help"),false);return 1;}
 private static int cast(CommandSourceStack s,ServerPlayer p,String id,int extra){var rite=GrandSpells.ALL.stream().filter(r->r.id().equals(id)).findFirst().orElse(null);if(rite==null){s.sendFailure(Component.translatable("commands.kelmagic.unknown_rite"));return 0;}var words=new java.util.ArrayList<>(rite.formula());for(int i=0;i<extra;i++)words.add("muk");if(words.size()>100){s.sendFailure(Component.translatable("commands.kelmagic.word_limit"));return 0;}var plan=SpellParser.plan(words);if(plan.effect()!=SpellParser.Effect.GRAND||!SpellEffects.execute(p,plan)){s.sendFailure(Component.translatable("kelmagic.no_target"));return 0;}s.sendSuccess(()->Component.translatable("commands.kelmagic.cast",id,p.getDisplayName()),true);return 1;}
 // Legacy loaded-only search retained for backwards compatibility. Use vanilla /locate for unexplored terrain.
 private static int locate(CommandSourceStack s,int radius){var l=s.getLevel();var origin=BlockPos.containing(s.getPosition());var chunk=new net.minecraft.world.level.ChunkPos(origin);BlockPos best=null;double dist=Double.MAX_VALUE;// Loaded-only compatibility alias; no codec serialization per piece.
  for(int x=chunk.x-radius;x<=chunk.x+radius;x++)for(int z=chunk.z-radius;z<=chunk.z+radius;z++){var c=l.getChunkSource().getChunk(x,z,net.minecraft.world.level.chunk.status.ChunkStatus.STRUCTURE_STARTS,false);if(c==null)continue;for(var start:c.getAllStarts().values())for(var at:dev.kelmagic.worldgen.ArchiveLocator.positions(start)){double d=at.distSqr(origin);if(d<dist){best=at;dist=d;}}}
  if(best==null){s.sendFailure(Component.translatable("commands.kelmagic.archive_not_found",radius));return 0;}var at=best;s.sendSuccess(()->Component.translatable("commands.kelmagic.archive_found",at.getX(),at.getY(),at.getZ()).withStyle(net.minecraft.ChatFormatting.GREEN).withStyle(st->st.withClickEvent(new net.minecraft.network.chat.ClickEvent(net.minecraft.network.chat.ClickEvent.Action.SUGGEST_COMMAND,"/tp @s "+at.getX()+" "+at.getY()+" "+at.getZ()))),false);return 1;
 }
 private MagicCommands(){}
}
